     "The <a href=\"/en/artists-dominica.html\">Dominica artists</a> hub then lets you move between profiles: the historic bands, the singers of the new generation and the live formations carrying bouyon to the festival. Each profile points to the others, because no single artist tells the island's story alone. The scene is an ensemble, and it is that ensemble Bouyon Shattaz works to make visible.",
     "Finally, the event that brings all of these worlds together remains the <a href=\"/en/wcmf-creole-festival.html\">World Creole Music Festival</a>, the WCMF, three nights in Roseau that place Dominica's Creole music in front of an audience from across the Caribbean. It is in that setting that the profile of Midnight Groovers takes its most concrete meaning in 2026."
